<div class="stats"><a class="stat" href="/admin/ats/jobs?status=published"><b><?= $stats['open'] ?></b><span>Open vacancies</span></a><a class="stat <?= $stats['pending'] ? 'alert' : '' ?>" href="/admin/ats/jobs?status=pending"><b><?= $stats['pending'] ?></b><span>Awaiting review</span></a><a class="stat" href="/admin/ats/applications?stage=Applied"><b><?= $stats['new'] ?></b><span>New applications</span></a><div class="stat"><b><?= $stats['interviews'] ?></b><span>Interviews scheduled</span></div><div class="stat"><b><?= $stats['hired'] ?></b><span>Hired (90 days)</span></div></div>
<div class="toolbar"><form method="get" class="toolbar grow" style="margin:0"><select name="job" data-autosubmit><option value="">All vacancies</option><?php foreach ($jobs as $j): ?><option value="<?= (int) $j['id'] ?>" <?= $jobId == $j['id'] ? 'selected' : '' ?>><?= e($j['title']) ?> (<?= (int) $j['n'] ?>)</option><?php endforeach; ?></select></form>
<a class="btn btn-ghost btn-sm" href="/admin/ats/applications">All applicants</a><a class="btn btn-ghost btn-sm" href="/admin/ats/jobs">Vacancies</a><a class="btn btn-ghost btn-sm" href="/admin/ats/reports">Reports</a><a class="btn btn-primary btn-sm" href="/admin/ats/job/new"><?= icon('plus', 15) ?> New vacancy</a></div>
<p class="muted xs">Drag a candidate card to another column to change the stage (no email is sent when dragging; open the profile to notify the candidate).</p>
<div class="kanban" id="kanban"><?php foreach ($cols as $stage => $cards): ?>
<div class="kcol" data-stage="<?= e($stage) ?>"><h3><?= e($stage) ?> <span><?= count($cards) ?></span></h3>
<?php foreach ($cards as $a): ?><a class="kcard" draggable="true" data-id="<?= (int) $a['id'] ?>" href="/admin/ats/application/<?= (int) $a['id'] ?>"><div style="display:flex;justify-content:space-between;gap:8px"><strong><?= e($a['name']) ?></strong><span class="badge <?= $a['fit_score'] >= 70 ? 'green' : ($a['fit_score'] >= 40 ? 'amber' : '') ?>"><?= (int) $a['fit_score'] ?>%</span></div><div class="muted xs"><?= e($a['job_title'] ?: 'Talent network') ?></div><div class="muted xs"><?= $a['rating'] ? str_repeat('★', (int) $a['rating']) . ' · ' : '' ?><?= e(ago($a['created_at'])) ?></div></a><?php endforeach; ?></div><?php endforeach; ?></div>
<script>(function(){var drag=null;document.querySelectorAll('.kcard').forEach(function(c){c.addEventListener('dragstart',function(e){drag=c;c.classList.add('drag');e.dataTransfer.effectAllowed='move'});c.addEventListener('dragend',function(){c.classList.remove('drag');document.querySelectorAll('.kcol').forEach(function(x){x.classList.remove('over')})})});
document.querySelectorAll('.kcol').forEach(function(col){col.addEventListener('dragover',function(e){e.preventDefault();col.classList.add('over')});col.addEventListener('dragleave',function(){col.classList.remove('over')});
col.addEventListener('drop',function(e){e.preventDefault();col.classList.remove('over');if(!drag)return;col.appendChild(drag);var fd=new FormData();fd.append('id',drag.dataset.id);fd.append('stage',col.dataset.stage);fd.append('_csrf','<?= e(csrf_token()) ?>');fetch('/admin/ats/move',{method:'POST',body:fd,headers:{Accept:'application/json'}}).then(function(r){return r.json()}).then(function(d){if(!d.ok)alert('Could not move the candidate.');document.querySelectorAll('.kcol').forEach(function(x){x.querySelector('h3 span').textContent=x.querySelectorAll('.kcard').length})})})})})();</script>
